/**
 * Synthesize GitLab webhook payloads from data you can *read* about a merge
 * request, so `agent-sdk gitlab replay` can exercise a `gitlabChannel()`
 * without Maintainer access to the project hook and without a tunnel.
 *
 * Payloads are shaped to satisfy the channel's parsers (`gitlab-webhook.ts`);
 * `undefined` fields are dropped by `JSON.stringify` before delivery.
 */
/**
 * Parse an MR URL (`https://<host>/<group>/<project>/-/merge_requests/N`) or
 * `group/project!N` (defaults to gitlab.com). Returns undefined otherwise.
 */
export function parseGitLabMrRef(raw) {
    const text = raw.trim();
    const url = text.match(/^(https?:\/\/[^/]+)\/(.+?)\/-\/merge_requests\/(\d+)(?:[/?#].*)?$/i);
    if (url !== null) {
        return build({
            origin: url[1],
            projectPath: url[2],
            iid: Number(url[3]),
        });
    }
    const bang = text.match(/^([\w.-]+(?:\/[\w.-]+)+)!(\d+)$/);
    if (bang !== null) {
        return build({
            origin: "https://gitlab.com",
            projectPath: bang[1],
            iid: Number(bang[2]),
        });
    }
    return undefined;
}
function build(input) {
    const { origin, projectPath, iid } = input;
    const path = projectPath.replace(/^\/+|\/+$/g, "");
    return {
        origin,
        projectPath: path,
        iid,
        url: `${origin}/${path}/-/merge_requests/${iid}`,
        label: `${path}!${iid}`,
    };
}
/** Webhook `object_kind`s replay knows how to synthesize. */
export const GITLAB_SYNTHESIZABLE_EVENTS = ["merge_request", "note", "pipeline", "push"];
export function isGitLabSynthesizableEvent(event) {
    return GITLAB_SYNTHESIZABLE_EVENTS.includes(event);
}
const EVENT_HEADERS = {
    merge_request: "Merge Request Hook",
    note: "Note Hook",
    pipeline: "Pipeline Hook",
    push: "Push Hook",
};
const FALLBACK_USER = {
    id: 1,
    username: "agent-sdk-replay",
    name: "agent-sdk replay",
};
function projectPayload(project) {
    return {
        id: project.id,
        name: project.name ?? project.path_with_namespace.split("/").at(-1),
        web_url: project.web_url,
        namespace: project.namespace?.full_path,
        path_with_namespace: project.path_with_namespace,
        default_branch: project.default_branch ?? "main",
    };
}
function mergeRequestAttributes(input) {
    const { mergeRequest, headSha, action, extra = {} } = input;
    return {
        id: mergeRequest.id,
        iid: mergeRequest.iid,
        title: mergeRequest.title,
        description: mergeRequest.description ?? "",
        state: mergeRequest.state,
        draft: mergeRequest.draft ?? mergeRequest.work_in_progress ?? false,
        work_in_progress: mergeRequest.work_in_progress ?? mergeRequest.draft ?? false,
        source_branch: mergeRequest.source_branch,
        target_branch: mergeRequest.target_branch,
        source_project_id: mergeRequest.source_project_id,
        target_project_id: mergeRequest.target_project_id,
        author_id: mergeRequest.author?.id,
        url: mergeRequest.web_url,
        last_commit: { id: headSha },
        labels: (mergeRequest.labels ?? []).map((title) => ({ title })),
        ...(action === undefined ? {} : { action }),
        ...extra,
    };
}
/** Build one GitLab-shaped payload for `event`. */
export function synthesizeGitLabEvent(input) {
    const { event, project, mergeRequest } = input;
    if (!isGitLabSynthesizableEvent(event)) {
        return { error: `cannot synthesize ${event}` };
    }
    const user = mergeRequest.author ?? FALLBACK_USER;
    const headSha = mergeRequest.sha ??
        mergeRequest.diff_refs?.head_sha ??
        "0000000000000000000000000000000000000000";
    const base = {
        object_kind: event,
        event_type: event,
        user: { id: user.id, username: user.username, name: user.name },
        project: projectPayload(project),
    };
    switch (event) {
        case "merge_request": {
            const action = input.action ?? "open";
            // `update` with new commits carries `oldrev`; the default dispatch keys
            // on it, so a synthesized update should look like a push, not an edit.
            const extra = action === "update" ? { oldrev: mergeRequest.diff_refs?.base_sha ?? headSha } : {};
            return {
                eventName: event,
                action,
                header: EVENT_HEADERS[event],
                payload: {
                    ...base,
                    object_attributes: mergeRequestAttributes({
                        mergeRequest,
                        headSha,
                        action,
                        extra,
                    }),
                    labels: (mergeRequest.labels ?? []).map((title) => ({ title })),
                },
            };
        }
        case "note": {
            const body = input.comment ?? "@cursor please take a look";
            return {
                eventName: event,
                header: EVENT_HEADERS[event],
                payload: {
                    ...base,
                    project_id: project.id,
                    object_attributes: {
                        id: Date.now() % 1_000_000_000,
                        note: body,
                        noteable_type: "MergeRequest",
                        noteable_id: mergeRequest.id,
                        author_id: user.id,
                        url: `${mergeRequest.web_url}#note_replay`,
                        description: body,
                    },
                    merge_request: mergeRequestAttributes({ mergeRequest, headSha }),
                },
            };
        }
        case "pipeline": {
            const pipeline = input.pipeline;
            return {
                eventName: event,
                header: EVENT_HEADERS[event],
                payload: {
                    object_kind: event,
                    user: base.user,
                    project: base.project,
                    object_attributes: {
                        id: pipeline?.id ?? 1,
                        ref: pipeline?.ref ?? mergeRequest.source_branch,
                        sha: pipeline?.sha ?? headSha,
                        source: pipeline?.source ?? "merge_request_event",
                        status: input.status ?? pipeline?.status ?? "success",
                        url: pipeline?.web_url,
                    },
                    merge_request: {
                        id: mergeRequest.id,
                        iid: mergeRequest.iid,
                        title: mergeRequest.title,
                        source_branch: mergeRequest.source_branch,
                        target_branch: mergeRequest.target_branch,
                        state: mergeRequest.state,
                        url: mergeRequest.web_url,
                    },
                },
            };
        }
        case "push": {
            const before = mergeRequest.diff_refs?.base_sha ?? "0000000000000000000000000000000000000000";
            return {
                eventName: event,
                header: EVENT_HEADERS[event],
                payload: {
                    object_kind: event,
                    event_name: event,
                    before,
                    after: headSha,
                    ref: `refs/heads/${mergeRequest.source_branch}`,
                    checkout_sha: headSha,
                    user_id: user.id,
                    user_username: user.username,
                    user_name: user.name,
                    project_id: project.id,
                    project: base.project,
                    commits: [],
                    total_commits_count: 0,
                },
            };
        }
    }
    const unexpected = event;
    throw new Error(`unexpected gitlab event ${String(unexpected)}`);
}
/** Choose events to replay: explicit list, `*` for every declared, else merge_request. */
export function selectGitLabReplayEvents(requested, declared) {
    const wanted = requested === undefined
        ? ["merge_request"]
        : requested.includes("*")
            ? [...declared]
            : [...requested];
    const events = [];
    const unsupported = [];
    for (const event of new Set(wanted)) {
        if (isGitLabSynthesizableEvent(event)) {
            events.push(event);
        }
        else {
            unsupported.push(event);
        }
    }
    return { events, unsupported };
}
